 public static void main(String[] a)throws Exception{Map<String,byte[]> entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b,a[3]):b);}}try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}if(a[3].equals("turret")){entries.put("dev/zomboid/turretpower/SoundEvents.class",events());entries.put("dev/zomboid/turretpower/FireEvents.class",fireEvents());}if(a[3].equals("decor"))entries.put("dev/zomboid/decor/BedEvents.class",bedEvents());int expected=switch(a[3]){case "turret"->9;case "survival"->4;case "decor"->3;default->throw new IllegalArgumentException();};if(hooks!=expected)throw new IllegalStateException(a[3]+" hooks "+hooks+" != "+expected);try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);out.putNextEntry(n);out.write(e.getValue());out.closeEntry();}}System.out.println(a[3]+" hooks "+hooks+" verified");}
